message.content:
{
  "build": [
    {
      "slot": "body",
      "from_character": "Harambe",
      "trait": "Silverback gorilla build: huge body, massive barrel chest and broad hunched back.",
      "how": "The main silhouette is a broad, upright gorilla torso carved as one thick wooden trunk."
    },
    {
      "slot": "head",
      "from_character": "Doge",
      "trait": "Shiba Inu head: round fluffy cheeks, short muzzle, small triangular upright ears and black nose.",
      "how": "An unmistakable Doge head grows directly from the trunk, with cheek fluff rendered as carved wooden scallops."
    },
    {
      "slot": "eyes",
      "from_character": "NPC Wojak",
      "trait": "Two dot eyes with a completely blank expression.",
      "how": "Two tiny charcoal dots sit widely spaced above the muzzle without eyelids or highlights."
    },
    {
      "slot": "mouth",
      "from_character": "Pepe the Frog",
      "trait": "Thick, wide reddish-brown lips in a flat smug line across the whole lower face.",
      "how": "Pepe's broad raised lips cross the lower muzzle as a dark warm-brown carved ridge."
    },
    {
      "slot": "jaw",
      "from_character": "Gigachad",
      "trait": "Extremely chiselled square jawline and sharp cheekbones with a short dark trimmed beard.",
      "how": "The bottom of the Shiba muzzle resolves into a square carved jaw edged by a charcoal beard-shaped inset."
    },
    {
      "slot": "arms",
      "from_character": "Wojak",
      "trait": "Thin pale human limbs with simple thin lineart and slumped shoulders.",
      "how": "Two conspicuously skinny, drooping human arms emerge from the enormous torso, carved from the same pale honey-colored wood."
    },
    {
      "slot": "feet",
      "from_character": "Tralalero Tralala",
      "trait": "Three legs each wearing a bright blue Nike-style sneaker with a white swoosh.",
      "how": "Three short wooden legs form a stable tripod beneath the trunk, each ending in a bright blue sneaker with a cream-white swoosh."
    },
    {
      "slot": "skin_or_palette",
      "from_character": "Tung Tung Tung Sahur",
      "trait": "Brown polished wood with wood-grain rings and warm orange-brown wood tones.",
      "how": "Every anatomical part is the same honey-brown carved wood, with the torso retaining a log cylinder's circular top rim and clearly drawn grain rings."
    },
    {
      "slot": "accessory",
      "from_character": "Tung Tung Tung Sahur",
      "trait": "A wooden baseball bat held in one hand.",
      "how": "One skinny hand grips a plain wooden baseball bat vertically beside the log-shaped torso."
    },
    {
      "slot": "style",
      "from_character": "Trollface",
      "trait": "Rough black MS-Paint scribble lineart with wrinkly, wobbling contours.",
      "how": "A few unmistakably wobbly black scribble creases bracket the cheeks and muzzle inside an otherwise clean, confidently drawn silhouette."
    },
    {
      "slot": "pose",
      "from_character": "Doge",
      "trait": "Head tilted and turned over the shoulder, viewed from a slight three-quarter angle.",
      "how": "The wooden Shiba head looks back over one shoulder while the broad torso faces slightly away."
    }
  ],
  "base_character": "Harambe",
  "concept": {
    "form": "A wooden silverback-shaped creature with Doge's head, skinny human arms, a log torso and three sneakered legs.",
    "face": "Doge supplies the pointed ears, fluffy cheek silhouette and short muzzle; NPC Wojak supplies blank dot eyes; Pepe the Frog supplies thick flat lips; Gigachad supplies the square bearded jaw; Trollface supplies scribbled cheek wrinkles.",
    "body_and_colors": "A huge, broad-backed gorilla torso is carved into an upright log cylinder with skinny slumped arms and three short legs; all anatomy and the bat share one honey-brown wooden material, using exactly five colors: honey tan, reddish brown, charcoal, cream-white and bright blue.",
    "pose": "Standing on a three-sneaker tripod, bat planted vertically in one hand, head tilted back over the shoulder.",
    "vibe": "Deadpan readiness for a deeply unnecessary confrontation.",
    "signature": "A huge Doge-headed wooden trunk balanced on three bright blue sneakers."
  },
  "name_ideas": [
    "Bimble",
    "Krumbo",
    "Zunko"
  ],
  "caption": "I brought a bat to the group chat.",
  "lore": "Someone carved a guard dog from the council's meeting table. It immediately grew three sneakers and appointed itself moderator.",
  "image_prompt": "Draw one coherent wooden meme creature with the overall massive barrel chest and broad hunched back of Harambe the silverback gorilla, adapted into one upright wooden log cylinder. Give it the unmistakable head of Doge the Shiba Inu: small upright triangular ears, large round scalloped fluffy cheeks, short muzzle and black nose, carved from the same wood as its body. Use NPC Wojak's two tiny blank dot eyes, Pepe the Frog's thick wide reddish-brown lips held in a flat line across the muzzle, and Gigachad's sharply squared jaw, angular cheekbones and short charcoal beard-shaped inset. Add Trollface's rough MS-Paint scribble creases around the cheeks as sparse internal details, not an additional face. Give it the thin drooping human arms of Wojak, clearly much skinnier than its huge torso. Make its entire anatomy the polished honey-brown wood of Tung Tung Tung Sahur, with a visible circular log rim at the shoulders and simple wood-grain rings on the torso; put Tung Tung Tung Sahur's wooden baseball bat upright in one hand. Give it the three legs and bright blue Nike-style sneakers with cream-white swooshes of Tralalero Tralala, arranged as a stable tripod. Use Doge's characteristic head tilt and over-the-shoulder three-quarter glance. All body parts are continuously carved from one wooden material, with no seams, pasted pieces, extra heads or extra faces. Exactly five flat colors: honey tan, reddish brown, charcoal, cream-white and bright blue; use cream-white for the solid background as well. One single character, full body, centered, clean confident lineart with only the specified sparse internal scribble creases, flat colours, one consistent palette, expressive face, on a solid single-colour background; no shadows, no gradients, no lighting effects, no floor, no background elements, no text, no watermark."
}
